import{_ as t,c as e,o as a,a4 as n}from"./chunks/framework.ttppV29E.js";const o="/assets/agents-list-page.DPwbRunY.png",m=JSON.parse('{"title":"Agents","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/index.md","filePath":"docs/agents/index.md","lastUpdated":1786714481000}'),r={name:"docs/agents/index.md"},i=n('<h1 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Preview Feature</p><p>Agents are in preview and may change. Available to allowlisted tenants only.</p></div><p>AireGlu agents are A2A-compliant autonomous agents that other agents, or any A2A-compatible client, can discover and delegate work to. Each agent is backed by an LLM, configured with a system prompt, advertised skills, and a set of MCP servers that provide its tools.</p><h2 id="what-is-a2a" tabindex="-1">What is A2A? <a class="header-anchor" href="#what-is-a2a" aria-label="Permalink to &quot;What is A2A?&quot;">​</a></h2><p>A2A (Agent2Agent) is an open protocol for agent interoperability. It defines a JSON-RPC interface and a discovery format (&quot;agent card&quot;) so that agents from different vendors can call each other in a standard way.</p><p>AireGlu agents implement the A2A protocol via the official <a href="https://github.com/a2aproject/a2a-dotnet" target="_blank" rel="noreferrer">a2a-dotnet SDK</a> at <strong>A2A protocol version 1.0</strong> (currently shipping as the <code>1.0.0-preview</code> package).</p><h2 id="a2a-vs-mcp" tabindex="-1">A2A vs MCP <a class="header-anchor" href="#a2a-vs-mcp" aria-label="Permalink to &quot;A2A vs MCP&quot;">​</a></h2><table><thead><tr><th></th><th>MCP</th><th>A2A</th></tr></thead><tbody><tr><td>What it exposes</td><td>Tools and resources for an LLM to invoke</td><td>A whole agent that other agents can talk to</td></tr><tr><td>Caller</td><td>An LLM (via an MCP client)</td><td>Another agent or an A2A-compatible client</td></tr><tr><td>Unit of work</td><td>A single tool call</td><td>A delegated task with multi-turn conversation</td></tr><tr><td>Building block</td><td>Endpoint → tool/resource</td><td>LLM + instructions + skills + MCP servers</td></tr></tbody></table><p>In AireGlu, agents <em>use</em> MCP servers internally. An agent&#39;s tools are the tools exposed by the MCP servers attached to it; its skills are the descriptive face it presents to the outside world.</p><h2 id="tenant-access" tabindex="-1">Tenant Access <a class="header-anchor" href="#tenant-access" aria-label="Permalink to &quot;Tenant Access&quot;">​</a></h2><p>Agent features are enabled per-tenant. If you don&#39;t see <strong>AI Tools &gt; Agents</strong> in the navigation, contact support to request access for your tenant.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Agent usage requires the following claims on your user account:</p><table><thead><tr><th>Action</th><th>Required Claim</th></tr></thead><tbody><tr><td>View agent list</td><td><code>list:AgentConfiguration</code></td></tr><tr><td>View agent details</td><td><code>view:AgentConfiguration</code></td></tr><tr><td>Create an agent</td><td><code>create:AgentConfiguration</code></td></tr><tr><td>Edit an agent</td><td><code>edit:AgentConfiguration</code></td></tr><tr><td>Delete an agent</td><td><code>delete:AgentConfiguration</code></td></tr><tr><td>Connect a client to an agent</td><td><code>run:Agent</code></td></tr></tbody></table><p>The first five claims cover agent management in the AireGlu UI. <code>run:Agent</code> is required to authenticate an A2A client against an agent. Without it the client will complete OAuth login but every JSON-RPC call will fail.</p><p>Contact your administrator if you do not have the required permissions.</p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><p>Agents are found under <strong>AI Tools &gt; Agents</strong> in the main navigation.</p><p><img src="'+o+'" alt="agents"></p>',19),s=[i];function d(l,c,h,g,p,u){return a(),e("div",null,s)}const f=t(r,[["render",d]]);export{m as __pageData,f as default};
